from common import *

import numpy as np
import random

# concepts:
# guide objects, connection paths, row/column connectivity, filling

# description:
# Identify guide objects and fill the path between each pair with a connection color.
# For each pair of guide objects, determine the row/column path and fill all non-guide
# objects or pixels along these paths with the connection color, ensuring all pairs are connected.

def main(input_grid):
    output_grid = input_grid.copy()
    # Identify unique colors of the guide objects
    guide_colors = [color for color in object_colors(input_grid, background=Color.BLACK)]
    connection_color = Color.GREY

    # Get coordinates of each guide object
    guide_positions = {}
    for color in guide_colors:
        positions = np.argwhere(input_grid == color)
        guide_positions[color] = positions

    # Connect each pair of guide objects
    for color, positions in guide_positions.items():
        for i in range(len(positions) - 1):
            start = positions[i]
            end = positions[i + 1]
            # Fill the path between the start and end positions
            x1, y1 = start
            x2, y2 = end
            if x1 == x2:
                # Same row: fill column path
                for y in range(min(y1, y2), max(y1, y2) + 1):
                    if output_grid[x1, y] == Color.BLACK:
                        output_grid[x1, y] = connection_color
            elif y1 == y2:
                # Same column: fill row path
                for x in range(min(x1, x2), max(x1, x2) + 1):
                    if output_grid[x, y1] == Color.BLACK:
                        output_grid[x, y1] = connection_color
            else:
                # Fill row first, then column
                for y in range(min(y1, y2), max(y1, y2) + 1):
                    if output_grid[x1, y] == Color.BLACK:
                        output_grid[x1, y] = connection_color
                for x in range(min(x1, x2), max(x1, x2) + 1):
                    if output_grid[x, y2] == Color.BLACK:
                        output_grid[x, y2] = connection_color

    return output_grid

def generate_input():
    # Create a grid with random dimensions
    width, height = np.random.randint(10, 15), np.random.randint(10, 15)
    grid = np.full((width, height), Color.BLACK)

    # Randomly choose guide colors
    num_guides = np.random.randint(2, 5)
    guide_colors = random.sample(Color.NOT_BLACK, num_guides)

    # Place pairs of guide objects in the grid
    for color in guide_colors:
        for _ in range(2):  # Place two guide objects for each color
            x, y = random_free_location_for_sprite(grid, np.array([[color]]), background=Color.BLACK)
            grid[x, y] = color

    return grid

